using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using EternalSteam.OpenWorld;
public static class InspectHud08Circle {public static object Main(){var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();return new{scene=EditorSceneManager.GetActiveScene().path,playing=Application.isPlaying,dirty=EditorSceneManager.GetActiveScene().isDirty,map=h.Layout.MapPanel.GetComponentsInChildren<RectTransform>(true).Select(r=>new{name=r.name,parent=r.parent.name,anchor=r.anchorMin.ToString(),pivot=r.pivot.ToString(),pos=r.anchoredPosition.ToString(),size=r.sizeDelta.ToString(),components=r.GetComponents<Component>().Select(c=>c.GetType().Name).ToArray()}).ToArray()};}}
